from typing import List

def generate_semi_primes(limit: int) -> List[int]:
    """
    Generates all semi-primes up to a given limit.
    Args:
        limit: The upper limit for generating semi-primes.
    Returns:
        A list of semi-primes up to the limit.
    """
    def is_prime(num: int) -> bool:
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    semi_primes = []
    primes = [i for i in range(2, limit) if is_prime(i)]
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            semi_prime = primes[i] * primes[j]
            if semi_prime <= limit:
                semi_primes.append(semi_prime)
    return sorted(set(semi_primes))

def solve(N: int) -> str:
    semi_primes = generate_semi_primes(N)
    for i in range(len(semi_primes)):
        for j in range(i, len(semi_primes)):
            if semi_primes[i] + semi_primes[j] == N:
                return "YES"
    return "NO"
